from itertools import permutations

HOUSES = range(5)


def _right_of(a, b):
    return a == b + 1


def _next_to(a, b):
    return abs(a - b) == 1


def _solve():
    for colors in permutations(["red", "green", "ivory", "yellow", "blue"]):
        red = colors.index("red")
        green = colors.index("green")
        ivory = colors.index("ivory")
        if not _right_of(green, ivory):
            continue
        for nations in permutations(
            ["Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"]
        ):
            englishman = nations.index("Englishman")
            norwegian = nations.index("Norwegian")
            if englishman != red:
                continue
            if norwegian != 0:
                continue
            if not _next_to(norwegian, colors.index("blue")):
                continue
            for drinks in permutations(
                ["coffee", "tea", "milk", "orange juice", "water"]
            ):
                coffee = drinks.index("coffee")
                tea = drinks.index("tea")
                milk = drinks.index("milk")
                if coffee != green:
                    continue
                if tea != nations.index("Ukrainian"):
                    continue
                if milk != 2:
                    continue
                for hobbies in permutations(
                    ["dancing", "painter", "reading", "football", "chess"]
                ):
                    painter = hobbies.index("painter")
                    football = hobbies.index("football")
                    if painter != colors.index("yellow"):
                        continue
                    if drinks[football] != "orange juice":
                        continue
                    if hobbies[nations.index("Japanese")] != "chess":
                        continue
                    for pets in permutations(
                        ["dog", "snail", "fox", "horse", "zebra"]
                    ):
                        if pets[nations.index("Spaniard")] != "dog":
                            continue
                        if pets[hobbies.index("dancing")] != "snail":
                            continue
                        if not _next_to(
                            hobbies.index("reading"), pets.index("fox")
                        ):
                            continue
                        if not _next_to(painter, pets.index("horse")):
                            continue
                        return nations, drinks, pets


_NATIONS, _DRINKS, _PETS = _solve()


def drinks_water():
    return _NATIONS[_DRINKS.index("water")]


def owns_zebra():
    return _NATIONS[_PETS.index("zebra")]
